-- 074_import_missing_leads.sql
-- Import Sara's contacts that were missing from public.leads, deduplicated from
-- the Master mailable export (2026-08-16). 140 people, all Sara's own
-- contacts with permission to contact; every row is dispositioned OK-mailable or
-- OK-relay (none do-not-contact). The leads table has no city/company/disposition
-- columns, so that provenance is preserved in notes.
--
-- Idempotent: ON CONFLICT (email) DO NOTHING. The unique email key is the real
-- check for 'already in the CRM' — any address already present is skipped, so this
-- is safe to re-run and safe even if the CSV's own 'In CRM' flag was stale.

on conflict (email) do nothing;
